 private static int kind=Integer.getInteger("blockbranch.reimaginedRemainingStart",3);private static boolean prepared,done,partial,metadata;private static long started,ready,cpuStart,allocatedStart,admissionCpu,admissionAllocated,planNanos,planAllocated;private static ReimaginedSites.Plan plan;private static StructureStart start;private static BoundingBox body;private static final List<ChunkPos> forced=new ArrayList<>();private static final List<Object> reports=new ArrayList<>();
 public static void register(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents.END_SERVER_TICK.register(server->{if(done)return;try{var level=server.overworld();var g=(RealisticGenerator)level.getChunkSource().getGenerator();String name=switch(kind){case 3->"jungle";case 4->"mansion";default->"monument";};boolean reload=Files.exists(Path.of(name+"-saved.json"));if(!prepared){if(!metadata){ReimaginedCompatibility.verify(level,g);metadata=true;}started=System.nanoTime();cpuStart=cpu();allocatedStart=allocated();long planningAllocated=allocated();plan=g.reimagined(level.getChunkSource().randomState()).ordered(kind,BlockPos.ZERO,6000000).stream().limit(12).map(ReimaginedSites.Region::plan).flatMap(Optional::stream).findFirst().orElseThrow();planNanos=System.nanoTime()-started;planAllocated=allocated()-planningAllocated;var holder=level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(ReimaginedStructures.key(kind));var chunk=level.getChunk(plan.x()>>4,plan.z()>>4,net.minecraft.world.level.chunk.status.ChunkStatus.STRUCTURE_STARTS);start=level.structureManager().getStartForStructure(holder.value(),chunk);require(start!=null&&start.isValid(),"Actual selected native "+name+" start");body=BoundingBox.encapsulatingBoxes(start.getPieces().stream().filter(p->!(p instanceof ReimaginedTreeClearPiece)).map(StructurePiece::getBoundingBox).toList()).orElseThrow();var all=start.getBoundingBox();var order=new ArrayList<ChunkPos>();for(int z=all.minZ()>>4;z<=all.maxZ()>>4;z++)for(int x=all.minX()>>4;x<=all.maxX()>>4;x++)order.add(new ChunkPos(x,z));if(Boolean.getBoolean("blockbranch.reimaginedReverse"))Collections.reverse(order);partial=Boolean.getBoolean("blockbranch.reimaginedPartial")&&!Files.exists(Path.of("partial.json"));if(partial)order=new ArrayList<>(order.subList(0,Math.max(1,order.size()/3)));for(var c:order){level.setChunkForced(c.x(),c.z(),true);forced.add(c);}ready=System.nanoTime();admissionCpu=cpu()-cpuStart;admissionAllocated=allocated()-allocatedStart;prepared=true;blockbranch.Blockbranch.LOGGER.info("REIMAGINED_REMAINING_ADMITTED {} {}ms {}",name,(ready-started)/1000000,body);return;}
 if(forced.stream().anyMatch(c->!level.areEntitiesLoaded(c.pack()))){require(System.nanoTime()-ready<120_000_000_000L,"Native entity admission deadline");return;}if(System.nanoTime()-ready<1_000_000_000L)return;
 if(partial){var core=(OceanMonumentPieces.MonumentBuilding)start.getPieces().getFirst();var uuids=level.getEntitiesOfClass(net.minecraft.world.entity.Mob.class,new net.minecraft.world.phys.AABB(body.minX(),body.minY(),body.minZ(),body.maxX()+1,body.maxY()+1,body.maxZ()+1)).stream().filter(e->e.getType()==net.minecraft.world.entity.EntityTypes.ELDER_GUARDIAN).map(e->e.getUUID().toString()).sorted().toList();var before=coverage(level,core.getBoundingBox());require(before.stream().anyMatch(v->!(boolean)v.get("featuresComplete"))&&before.stream().anyMatch(v->(boolean)v.get("featuresComplete")),"Genuine partial native core FEATURES coverage before save");var requested=forced.stream().map(ChunkPos::pack).toList();for(var c:forced)level.setChunkForced(c.x(),c.z(),false);forced.clear();server.saveEverything(false,true,true);var after=coverage(level,core.getBoundingBox());require(after.stream().anyMatch(v->!(boolean)v.get("featuresComplete")),"Native core remains genuinely incomplete after save flush");write("partial.json",Map.of("children",childBoxes(core),"elderUUIDs",uuids,"forcedChunks",requested,"beforeSaveCoreCoverage",before,"afterSaveCoreCoverage",after));Files.writeString(Path.of("remaining-result.txt"),"PASS");done=true;server.halt(false);return;}
 var chests=new ArrayList<ChestBlockEntity>();var dispensers=new ArrayList<DispenserBlockEntity>();int levers=0,pistons=0,gold=0,sponges=0;for(var at:BlockPos.betweenClosed(body.minX(),body.minY(),body.minZ(),body.maxX(),body.maxY(),body.maxZ())){var s=level.getBlockState(at);if(s.is(Blocks.LEVER))levers++;if(s.is(Blocks.STICKY_PISTON))pistons++;if(s.is(Blocks.GOLD_BLOCK))gold++;if(s.is(Blocks.WET_SPONGE))sponges++;if(s.hasBlockEntity()){var be=level.getBlockEntity(at);if(be instanceof ChestBlockEntity c)chests.add(c);if(be instanceof DispenserBlockEntity d)dispensers.add(d);}}
 var residents=level.getEntitiesOfClass(net.minecraft.world.entity.Mob.class,new net.minecraft.world.phys.AABB(body.minX(),body.minY(),body.minZ(),body.maxX()+1,body.maxY()+1,body.maxZ()+1).inflate(8)).stream().filter(m->{String id=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(m.getType()).toString();return id.endsWith("evoker")||id.endsWith("vindicator")||id.endsWith("allay")||id.endsWith("elder_guardian");}).sorted(Comparator.comparing(m->m.getUUID().toString())).toList();var row=new LinkedHashMap<String,Object>();row.put("name",name);row.put("plan",plan);row.put("admissionNanos",ready-started);row.put("admissionProcessCpuNanos",admissionCpu);row.put("admissionProcessAllocatedBytes",admissionAllocated);row.put("planningNanos",planNanos);row.put("planningProcessAllocatedBytes",planAllocated);row.put("body",List.of(body.minX(),body.minY(),body.minZ(),body.maxX(),body.maxY(),body.maxZ()));row.put("chunks",forced.size());row.put("chests",chests.size());row.put("dispensers",dispensers.size());row.put("levers",levers);row.put("stickyPistons",pistons);row.put("goldBlocks",gold);row.put("wetSponges",sponges);row.put("residents",residents.stream().map(m->Map.of("id",net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(m.getType()).toString(),"uuid",m.getUUID().toString())).toList());var context=net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(level);row.put("pieces",start.getPieces().stream().map(p->p.createTag(context).toString()).toList());row.put("reload",reload);if(!reload)row.put("nativeChestWitness",chests.stream().map(c->nativeChest(level,c)).toList());write(name+"-before-validation.json",row);var nativeFloating=new HashSet<Long>();for(var p:start.getPieces())if(p instanceof WoodlandMansionPieces.WoodlandMansionPiece m)for(var info:m.template().filterBlocks(m.templatePosition(),m.placeSettings().copy().setBoundingBox(null),Blocks.LILY_PAD))nativeFloating.add(info.pos().asLong());row.put("originalNativeFloatingLilyPads",nativeFloating.size());for(var p:start.getPieces())if(p instanceof ReimaginedTreeClearPiece)row.put("retainedForest",ReimaginedForest.verify(level,p.getBoundingBox(),body));row.put("groundedCollidableBlocks",ReimaginedGrounding.verify(level,body,nativeFloating,nativeArchJoins(level,start)));for(var c:forced){var q=((blockbranch.cubic.SparsePostProcessingAccess)level.getChunk(c.x(),c.z())).blockbranch$postProcessing(false);require(q==null||q.snapshot().length==0,"Native sparse updates drained");}if(kind==3)row.put("routeCells",ReimaginedRoutes.verify(level,(ReimaginedLayoutPiece)start.getPieces().stream().filter(p->p instanceof ReimaginedLayoutPiece).findFirst().orElseThrow()));if(kind==4)row.put("routeCells",ReimaginedRoutes.mansion(level,(ReimaginedMansionPiece)start.getPieces().stream().filter(p->p instanceof ReimaginedMansionPiece).findFirst().orElseThrow()));if(kind==4)row.put("servicePassageCells",ReimaginedRoutes.servicePassage(level,(ReimaginedMansionPiece)start.getPieces().stream().filter(p->p instanceof ReimaginedMansionPiece).findFirst().orElseThrow(),reload));if(kind==5)row.put("routeCells",ReimaginedRoutes.sanctuary(level,(ReimaginedSanctuaryPiece)start.getPieces().get(1)));
 if(kind==3){require(start.getPieces().stream().anyMatch(p->p instanceof JungleTemplePiece),"Original native jungle core");require(chests.size()==2&&dispensers.size()==2&&levers==3&&pistons>=2,"Native jungle loot and mechanism counts");}if(kind==4){require(start.getPieces().stream().filter(p->p instanceof WoodlandMansionPieces.WoodlandMansionPiece).count()>20,"Original native mansion room graph");require(!residents.isEmpty(),"Native occupied mansion residents");}if(kind==5){require(start.getPieces().getFirst() instanceof OceanMonumentPieces.MonumentBuilding,"Native monument first piece/reload graph contract");require(residents.stream().filter(m->net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(m.getType()).getPath().equals("elder_guardian")).count()==3,"Exactly three original elders");require(gold==8,"Original monument core gold quota");var nativeCore=(OceanMonumentPieces.MonumentBuilding)start.getPieces().getFirst();row.put("nativeChildBoxes",childBoxes(nativeCore));var completeCoverage=coverage(level,nativeCore.getBoundingBox());require(completeCoverage.stream().allMatch(v->(boolean)v.get("featuresComplete")),"Full native core FEATURES coverage after completion");row.put("completeCoreCoverage",completeCoverage);if(Files.exists(Path.of("partial.json"))){var partialRecord=com.google.gson.JsonParser.parseString(Files.readString(Path.of("partial.json"))).getAsJsonObject();require(new com.google.gson.Gson().toJsonTree(childBoxes(nativeCore)).equals(partialRecord.get("children")),"Partial reload restores every native child box at fitted Y");var ids=residents.stream().map(e->e.getUUID().toString()).collect(java.util.stream.Collectors.toSet());for(var id:partialRecord.getAsJsonArray("elderUUIDs"))require(ids.contains(id.getAsString()),"Partial native elder UUID preserved");}var core=start.getPieces().getFirst().getBoundingBox();var inside=new BlockPos((core.minX()+core.maxX())/2,core.minY()+5,(core.minZ()+core.maxZ())/2);var outside=new BlockPos(body.minX()+2,core.minY()+5,body.minZ()+2);require(g.getMobsAt(level,level.structureManager(),net.minecraft.world.entity.MobCategory.MONSTER,inside).unwrap().stream().anyMatch(e->e.value().type()==net.minecraft.world.entity.EntityTypes.GUARDIAN),"Native core guardian override");require(g.getMobsAt(level,level.structureManager(),net.minecraft.world.entity.MobCategory.MONSTER,outside).unwrap().stream().noneMatch(e->e.value().type()==net.minecraft.world.entity.EntityTypes.GUARDIAN),"Added sanctuary does not expand native guardian spawn area");}
 if(reload){var old=com.google.gson.JsonParser.parseString(Files.readString(Path.of(name+"-saved.json"))).getAsJsonObject();require(hash(level,body).equals(old.get("hash").getAsString()),"Exact saved architecture "+name);require(new com.google.gson.Gson().toJsonTree(row.get("residents")).equals(old.get("residents")),"Native resident UUIDs preserved "+name);for(var c:chests)require(c.isEmpty()&&c.getLootTable()==null,"Consumed loot retained");var edit=NativeOrdinaryQualification.pos(old.getAsJsonArray("edit"));require(level.getBlockState(edit).is(Blocks.OAK_PLANKS),"Player repair retained");}
 else{row.put("lootTables",chests.stream().map(c->nativeChest(level,c)).toList());row.put("dispenserLoot",dispensers.stream().map(c->{require(c.getLootTable()!=null,"Original native dispenser loot");return c.getLootTable().identifier().toString();}).toList());for(var c:chests){c.unpackLootTable(null);c.clearContent();c.setChanged();}var edit=new BlockPos(body.minX(),body.minY(),body.minZ());level.setBlock(edit,Blocks.OAK_PLANKS.defaultBlockState(),3);row.put("edit",List.of(edit.getX(),edit.getY(),edit.getZ()));row.put("hash",hash(level,body));String reference=System.getProperty("blockbranch.reimaginedReference","");if(!reference.isEmpty()){var expected=com.google.gson.JsonParser.parseString(Files.readString(Path.of(reference).resolve(name+"-saved.json"))).getAsJsonObject();require(row.get("hash").equals(expected.get("hash").getAsString()),"Reverse/partial order exact complete block-state hash "+name);}write(name+"-saved.json",row);}
 reports.add(row);write(reload?"remaining-reopen.json":"remaining-fresh.json",reports);for(var c:forced)level.setChunkForced(c.x(),c.z(),false);forced.clear();server.saveEverything(false,true,true);prepared=false;if(++kind>Integer.getInteger("blockbranch.reimaginedRemainingEnd",5)){Files.writeString(Path.of("remaining-result.txt"),"PASS");done=true;server.halt(false);}
 }catch(Throwable t){done=true;blockbranch.Blockbranch.LOGGER.error("REIMAGINED_REMAINING_FAIL",t);try{Files.writeString(Path.of("remaining-result.txt"),"FAIL "+t);}catch(Exception ignored){}server.halt(false);}});}
 // Native monument uses deliberate edge-contact stepped arches and wing ribs. Added architecture is excluded.
 static List<Map<String,Object>> coverage(ServerLevel level,BoundingBox box){var rows=new ArrayList<Map<String,Object>>();for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++)for(int x=box.minX()>>4;x<=box.maxX()>>4;x++){var holder=level.getChunkSource().chunkMap.getUpdatingChunkIfPresent(new ChunkPos(x,z).pack());var status=holder==null?null:holder.getPersistedStatus();rows.add(Map.of("x",x,"z",z,"status",status==null?"absent":status.toString(),"featuresComplete",status!=null&&status.isOrAfter(net.minecraft.world.level.chunk.status.ChunkStatus.FEATURES)));}return rows;}
 static List<List<Integer>> childBoxes(OceanMonumentPieces.MonumentBuilding core){return ((blockbranch.mixin.cubic.ReimaginedMonumentChildren)core).blockbranch$children().stream().map(p->{var b=p.getBoundingBox();return List.of(b.minX(),b.minY(),b.minZ(),b.maxX(),b.maxY(),b.maxZ());}).toList();}
 static Map<Long,List<Long>> nativeArchJoins(ServerLevel level,StructureStart start){var joins=new HashMap<Long,List<Long>>();for(var piece:start.getPieces())if(piece instanceof OceanMonumentPieces.MonumentBuilding){var box=piece.getBoundingBox();for(var p:BlockPos.betweenClosed(box.minX(),box.minY(),box.minZ(),box.maxX(),box.maxY(),box.maxZ()))if(nativeMasonry(level,p))for(int dx=-1;dx<=1;dx++)for(int dy=-1;dy<=1;dy++)for(int dz=-1;dz<=1;dz++)if(Math.abs(dx)+Math.abs(dy)+Math.abs(dz)==2){var q=p.offset(dx,dy,dz);if(box.isInside(q)&&nativeMasonry(level,q))joins.computeIfAbsent(p.asLong(),k->new ArrayList<>()).add(q.asLong());}var local=(blockbranch.mixin.cubic.ReimaginedPieceCoordinates)piece;for(int x:new int[]{25,32})for(int z:new int[]{25,32}){var a=local.blockbranch$local(x,19,z).immutable();var b=local.blockbranch$local(x==25?26:31,20,z==25?26:31).immutable();require(level.getBlockState(a).is(Blocks.PRISMARINE_BRICKS)&&level.getBlockState(b).is(Blocks.PRISMARINE_BRICKS),"Exact native generateRoofPiece corner contact");joins.computeIfAbsent(a.asLong(),k->new ArrayList<>()).add(b.asLong());joins.computeIfAbsent(b.asLong(),k->new ArrayList<>()).add(a.asLong());}}return joins;}
 static boolean nativeMasonry(ServerLevel l,BlockPos p){var s=l.getBlockState(p);return s.is(Blocks.PRISMARINE)||s.is(Blocks.PRISMARINE_BRICKS)||s.is(Blocks.DARK_PRISMARINE)||s.is(Blocks.SEA_LANTERN);}
 static String nativeChest(ServerLevel level,ChestBlockEntity chest){if(chest.getLootTable()!=null)return chest.getLootTable().identifier().toString();require(kind==4,"Native non-mansion loot table");for(var p:start.getPieces())if(p instanceof WoodlandMansionPieces.WoodlandMansionPiece m)for(var info:m.template().filterBlocks(m.templatePosition(),m.placeSettings().copy().setBoundingBox(null),Blocks.CHEST))if(info.pos().equals(chest.getBlockPos())){var expected=info.nbt();var actual=chest.saveWithoutMetadata(level.registryAccess());try{write("mansion-fixed-chest-"+chest.getBlockPos().getX()+"-"+chest.getBlockPos().getZ()+".json",Map.of("template",((blockbranch.mixin.cubic.ReimaginedTemplateName)m).blockbranch$reimaginedTemplate(),"position",chest.getBlockPos().toShortString(),"expectedNBT",expected==null?"null":expected.toString(),"actualNBT",actual.toString()));}catch(Exception e){throw new RuntimeException(e);}require(expected==null||!expected.contains("LootTable"),"Native fixed chest must not lose a loot table");boolean items=expected!=null&&(expected.getList("Items").map(v->!v.isEmpty()).orElse(false)||expected.getList("items").map(v->!v.isEmpty()).orElse(false));if(!items)require(chest.isEmpty(),"Native empty furniture chest stays empty");else for(String key:List.of("Items","items"))require(Objects.equals(expected.get(key),actual.get(key)),"Native fixed contents remain exact "+key);return items?"native-fixed-items":"native-empty-furniture";}try{write("unmatched-native-chest.json",Map.of("position",chest.getBlockPos().toShortString(),"actual",chest.saveWithoutMetadata(level.registryAccess()).toString(),"nearbyPieces",start.getPieces().stream().filter(p->p.getBoundingBox().isInside(chest.getBlockPos())).map(p->p.createTag(net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(level)).toString()).toList()));}catch(Exception e){throw new RuntimeException(e);}throw new AssertionError("Missing loot table has no original native chest template witness "+chest.getBlockPos());}
 static long cpu(){return ((com.sun.management.OperatingSystemMXBean)java.lang.management.ManagementFactory.getOperatingSystemMXBean()).getProcessCpuTime();}static long allocated(){return ((com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean()).getTotalThreadAllocatedBytes();}
 static String hash(ServerLevel l,BoundingBox b)throws Exception{var digest=java.security.MessageDigest.getInstance("SHA-256");byte[] word=new byte[4];for(var p:BlockPos.betweenClosed(b.minX(),b.minY(),b.minZ(),b.maxX(),b.maxY(),b.maxZ())){int id=Block.getId(l.getBlockState(p));for(int i=0;i<4;i++)word[i]=(byte)(id>>>(i*8));digest.update(word);}return HexFormat.of().formatHex(digest.digest());}
 static void require(boolean yes,String message){if(!yes)throw new AssertionError(message);}static void write(String name,Object value)throws Exception{Files.writeString(Path.of(name),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(value));}
